add(HKX,"role",[
("bloodborne","med","You find vomit in a room. How should it be cleaned?","Encuentras vómito en un cuarto. ¿Cómo se limpia?",["Gloves and PPE, absorb it, clean, then disinfect with an EPA-registered product","Spray air freshener","Wipe with a bath towel and reuse it","Vacuum it"],["Con guantes y EPP: absorber, limpiar y desinfectar con producto registrado por EPA","Echar aromatizante","Limpiar con toalla de baño y reusarla","Aspirarlo"],"CDC: clean then disinfect body fluids with PPE.","CDC: limpiar y desinfectar con EPP.",CDCC),
("bloodborne","med","After removing gloves, what do you do?","Después de quitarte los guantes, ¿qué haces?",["Wash your hands","Nothing","Reuse the gloves","Wipe on your uniform"],["Lavarte las manos","Nada","Reusarlos","Limpiarte en el uniforme"],"OSHA: wash hands after glove removal.","OSHA: lavarse tras quitarse guantes.",BBP),
("chemicals","easy","Can you use a cleaner from an unlabeled spray bottle?","¿Puedes usar un limpiador de una botella sin etiqueta?",["No — report it and get a labeled one","Yes, smell it first","Yes, if blue","Yes, mix it"],["No; repórtalo y usa una etiquetada","Sí, olerlo primero","Sí, si es azul","Sí, mezclarlo"],"HazCom: containers must be labeled.","HazCom: deben estar etiquetados.",HAZ),
("chemicals","med","What does a GHS pictogram with a flame mean?","¿Qué significa el pictograma GHS con flama?",["Flammable","Toxic to fish","Under pressure","Safe"],["Inflamable","Tóxico para peces","Bajo presión","Seguro"],"OSHA HazCom pictograms.","Pictogramas HazCom.",HAZ),
("chemicals","med","What does the GHS 'corrosion' pictogram warn about?","¿De qué advierte el pictograma de 'corrosión'?",["It can burn skin/eyes or damage metal","It's flammable","It's a gas","It's food-safe"],["Puede quemar piel/ojos o dañar metal","Inflamable","Es gas","Es apto para comida"],"Corrosives need gloves and eye protection.","Usar guantes y lentes.",HAZ),
("ergonomics","easy","How can you reduce back strain making beds?","¿Cómo reduces el esfuerzo de espalda al tender camas?",["Bend your knees, kneel at corners, and avoid twisting","Lift the mattress with your back","Bend at the waist all day","Work faster"],["Doblar rodillas, hincarte en esquinas y no girar","Levantar el colchón con la espalda","Agacharte de cintura todo el día","Trabajar más rápido"],"OSHA hotel housekeeping ergonomics.","Ergonomía OSHA.",LIFT),
("ergonomics","med","Why push a cart instead of pulling it?","¿Por qué empujar el carro en vez de jalarlo?",["Pushing is easier on your back and you can see ahead","Pulling is safer","No difference","Carts only pull"],["Empujar cuida tu espalda y ves adelante","Jalar es más seguro","Igual","Solo se jalan"],"OSHA: pushing reduces strain.","Empujar reduce esfuerzo.",LIFT),
("safety","med","A guest is acting aggressively in the hallway. What do you do?","Un huésped actúa agresivo en el pasillo. ¿Qué haces?",["Leave the area, get to a safe place, and call the desk/manager (911 if danger)","Argue","Block their way","Ignore and keep working next to them"],["Alejarte, ponerte a salvo y llamar a recepción o gerente (911 si hay peligro)","Discutir","Bloquearle el paso","Ignorar y seguir junto a él"],"Your safety first; report.","Tu seguridad primero.",BP),
("safety","med","Many cities and brands give housekeepers safety buttons/devices. When do you use one?","Muchos hoteles dan botones de pánico. ¿Cuándo lo usas?",["Whenever you feel threatened or unsafe in a room or hallway","Only for fire","Never","Only to call for towels"],["Siempre que te sientas amenazada o insegura","Solo en incendio","Nunca","Solo para pedir toallas"],"Panic buttons are for any threat.","Para cualquier amenaza.",BP),
("weapons","hard","You see a gun or drugs in a room. What do you do?","Ves un arma o drogas en un cuarto. ¿Qué haces?",["Don't touch anything, leave, and tell your manager right away","Move it to a drawer","Take a picture and post it","Keep cleaning"],["No tocar nada, salir y avisar de inmediato al gerente","Guardarlo en un cajón","Tomar foto y publicarla","Seguir limpiando"],"Leave it for management/police.","Que lo atiendan gerencia o policía.",BP),
("lost_found","easy","You find cash on the nightstand of a checked-out room. What do you do?","Encuentras dinero en el buró de un cuarto que ya salió. ¿Qué haces?",["Turn it in to lost and found with room and date","Keep it as a tip","Split it","Leave it"],["Entregarlo a objetos perdidos con cuarto y fecha","Quedártelo como propina","Repartirlo","Dejarlo"],"Unless clearly marked as a tip, it's lost property.","Si no dice propina, es objeto perdido.",BP),
("tips","med","An envelope on the pillow says 'Housekeeping — thank you'. What is it?","Un sobre en la almohada dice 'Housekeeping — gracias'. ¿Qué es?",["A tip for you — follow the hotel's tip policy","Lost property","Guest trash","Something to return"],["Una propina para ti; sigue la política del hotel","Objeto perdido","Basura","Algo para devolver"],"Marked tips belong to housekeeping per policy.","Las propinas marcadas son de housekeeping.",BP),
("pests","med","Besides bed bugs, which pest sign should you report from a room?","Aparte de chinches, ¿qué plaga reportas de un cuarto?",["Cockroaches, mouse droppings, or ants","Dust","Lint","Hair"],["Cucarachas, excremento de ratón u hormigas","Polvo","Pelusa","Cabello"],"Report any pest so pest control can act.","Reporta cualquier plaga.",BB),
("glass","easy","How do you pick up broken glass?","¿Cómo recoges vidrio roto?",["Use a broom and dustpan, never bare hands; wrap it before trash","With your hands","With a towel and shake it","Vacuum big pieces"],["Con escoba y recogedor; nunca con la mano; envolverlo","Con la mano","Con toalla y sacudirla","Aspirar los pedazos grandes"],"Prevents cuts to you and trash handlers.","Evita cortadas.",BP),
("door","easy","When you finish a room, what do you check before leaving?","Al terminar un cuarto, ¿qué revisas antes de salir?",["Door closes and locks behind you","Lights on","TV on","Window open"],["Que la puerta cierre con seguro","Luces prendidas","Tele prendida","Ventana abierta"],"Secure the room.","Asegura el cuarto.",BP),
("pool","easy","You see a child alone in the pool area. What do you do?","Ves a un niño solo en la alberca. ¿Qué haces?",["Stay nearby and alert the front desk so a parent is found","Ignore","Leave","Jump in"],["Quedarte cerca y avisar a recepción para encontrar a sus papás","Ignorar","Irte","Meterte"],"Unattended children near water are a drowning risk.","Riesgo de ahogamiento.","https://www.cdc.gov/drowning/prevention/index.html"),
])
